import{_ as a,c as r,o as t,a4 as n}from"./chunks/framework.BU14wsQo.js";const o="/ai/daily/2026-06-03/0-MAjjp3xIwi_-B5O5ARx.mp4",u=JSON.parse('{"title":"AI大事件 2026/6/3","description":"NVIDIA 智能体堆栈、Devin Desktop 与 Claude Code 工作流更新继续推高 agent 产品线，OpenWebRL、视频生成压缩和可解释性研究则把底层能力继续往前推。","frontmatter":{"linkTitle":"06-03 AI大事件","title":"AI大事件 2026/6/3","weight":29,"breadcrumbs":false,"comments":true,"description":"NVIDIA 智能体堆栈、Devin Desktop 与 Claude Code 工作流更新继续推高 agent 产品线，OpenWebRL、视频生成压缩和可解释性研究则把底层能力继续往前推。"},"headers":[],"relativePath":"ai/daily/cn/2026-06/2026-06-03.md","filePath":"AI/daily/cn/2026-06/2026-06-03.md","lastUpdated":1780462919000}'),s={name:"ai/daily/cn/2026-06/2026-06-03.md"};function i(l,e,h,g,p,d){return t(),r("div",null,[...e[0]||(e[0]=[n(`<h1 align="center">2026-06-03 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NVIDIA 智能体堆栈、Devin Desktop 与 Claude Code 动态工作流一起把 agent 开发体验往生产环境推进 🚀</span></span>
<span class="line"><span>前沿研究聚焦网页智能体自进化、视频生成显存压缩和特征可解释性，底层能力继续加厚 🧠</span></span>
<span class="line"><span>美国 AI 行政令、Project Glasswing 和青年 AI 安全议题同步升温，发布前评估与安全治理进入主线 ⚖️</span></span>
<span class="line"><span>Alphabet 800 亿美元融资、SK 海力士扩产和 Travelers 理赔助手显示 AI 基建与行业落地继续扩张 ☁️</span></span>
<span class="line"><span>headroom、TradingAgents、impeccable 与 ECC 都很工具化，开发者生态仍在用开源小工具补齐工作流 🛠️</span></span>
<span class="line"><span>开放模型份额、主权模型和办公技能套件说明生态竞争不只看模型能力，也看组织和工作流 (๑•̀ㅂ•́)و✧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-英伟达发布全新智能体堆栈" tabindex="-1">1. 英伟达发布全新智能体堆栈 <a class="header-anchor" href="#_1-英伟达发布全新智能体堆栈" aria-label="Permalink to &quot;1. 英伟达发布全新智能体堆栈&quot;">​</a></h3><p><strong>NVIDIA</strong> 发布新的安全智能体系统栈，重点是给端侧智能体开发加入更明确的安全沙箱和隔离机制，减少工具调用、文件访问和上下文泄露带来的风险。对正在把 agent 接入本地设备和企业环境的团队来说，这类安全运行层会越来越像标配 (๑•̀ㅂ•́)و✧。来源：<a href="https://nvda.ws/4u7K4g7" target="_blank" rel="noreferrer">NVIDIA</a></p><h3 id="_2-windsurf-更名为-devin-桌面端" tabindex="-1">2. Windsurf 更名为 Devin 桌面端 <a class="header-anchor" href="#_2-windsurf-更名为-devin-桌面端" aria-label="Permalink to &quot;2. Windsurf 更名为 Devin 桌面端&quot;">​</a></h3><p><strong>Windsurf</strong> 正式更名为 <strong>Devin Desktop</strong>，把云端智能体能力带到本地桌面工作流里。这个变化不只是品牌调整，更像是把“AI 编程助手”推进到本地任务执行、文件上下文和工程环境协作的下一层 🛠️。来源：<a href="https://devin.ai/blog/windsurf-is-now-devin-desktop" target="_blank" rel="noreferrer">Devin</a></p><h3 id="_3-微软首款高级推理-ai-模型-mai-thinking-1-发布" tabindex="-1">3. 微软首款高级推理 AI 模型 MAI-Thinking-1 发布 <a class="header-anchor" href="#_3-微软首款高级推理-ai-模型-mai-thinking-1-发布" aria-label="Permalink to &quot;3. 微软首款高级推理 AI 模型 MAI-Thinking-1 发布&quot;">​</a></h3><p><strong>微软</strong> 在 Build 2026 发布首款高级推理模型 <strong>MAI-Thinking-1</strong>，定位为“中等规模”，并称其在关键软件工程基准测试中达到领先模型水平。微软强调模型使用干净数据从头训练、未从第三方模型蒸馏，这也让外界继续观察它与 OpenAI 合作之外的自研路线 ( •̀ ω •́ )。来源：<a href="https://www.theverge.com/tech/941664/microsoft-ai-model-reasoning-mai-thinking-1-build-2026" target="_blank" rel="noreferrer">The Verge</a></p><h3 id="_4-holo3-1-快速本地计算机使用智能体" tabindex="-1">4. Holo3.1：快速本地计算机使用智能体 <a class="header-anchor" href="#_4-holo3-1-快速本地计算机使用智能体" aria-label="Permalink to &quot;4. Holo3.1：快速本地计算机使用智能体&quot;">​</a></h3><p><strong>Holo3.1</strong> 是基于 Qwen 模型家族的计算机使用智能体系列，覆盖桌面、网页和移动环境，提供 <strong>0.8B、4B、9B 和 35B-A3B</strong> 四种尺寸。35B-A3B 在 <strong>AndroidWorld</strong> 得分从 <strong>67%</strong> 提升至 <strong>79.3%</strong>；在 DGX Spark 上，NVFP4 量化相比 BF16 实现 <strong>1.74 倍</strong> token 吞吐量提升，并把平均步骤时间从 <strong>6.8 秒</strong> 缩短到 <strong>3.3 秒</strong> 🚀。来源：<a href="https://huggingface.co/blog/Hcompany/holo31" target="_blank" rel="noreferrer">Hugging Face</a></p><h3 id="_5-claude-code-新增动态工作流功能" tabindex="-1">5. Claude Code 新增动态工作流功能 <a class="header-anchor" href="#_5-claude-code-新增动态工作流功能" aria-label="Permalink to &quot;5. Claude Code 新增动态工作流功能&quot;">​</a></h3><p><strong>Claude Code</strong> 新增动态工作流能力，允许模型在运行时创建和协调多智能体框架来处理复杂任务。它通过 JavaScript 工作流生成拥有独立上下文窗口的子代理，适合研究、安全分析、代码审查等高价值长任务，但通常会消耗更多 token，最佳实践仍在演化中 🛠️。来源：<a href="https://claude.com/blog/a-harness-for-every-task-dynamic-workflows-in-claude-code" target="_blank" rel="noreferrer">Claude</a></p><h3 id="_6-google-deepmind-开源科学智能体工具包" tabindex="-1">6. Google DeepMind 开源科学智能体工具包 <a class="header-anchor" href="#_6-google-deepmind-开源科学智能体工具包" aria-label="Permalink to &quot;6. Google DeepMind 开源科学智能体工具包&quot;">​</a></h3><p><strong>Google DeepMind Science Skills</strong> 已在 GitHub 发布，面向科学发现场景提供专用工具包。它强调科学基础能力和更高 token 效率，适合把实验、检索、分析等步骤编进自主智能体工作流里 🧬。来源：<a href="https://x.com/googleaidevs/status/2061924472245153863" target="_blank" rel="noreferrer">Google AI for Developers</a></p><h3 id="_7-runway-api-推出-aleph-2-0-视频编辑功能" tabindex="-1">7. Runway API 推出 Aleph 2.0 视频编辑功能 <a class="header-anchor" href="#_7-runway-api-推出-aleph-2-0-视频编辑功能" aria-label="Permalink to &quot;7. Runway API 推出 Aleph 2.0 视频编辑功能&quot;">​</a></h3><p><strong>Runway API</strong> 推出 <strong>Aleph 2.0</strong> 视频编辑能力，支持把精准视频编辑集成到应用、产品和平台中。官方给出的能力边界是多镜头序列、最长 <strong>30 秒</strong>、<strong>1080p</strong> 分辨率，并且只修改用户指定部分，视频生成正在继续向可控编辑靠拢 🎬。来源：<a href="https://x.com/runwayml/status/2061895998545244342" target="_blank" rel="noreferrer">Runway</a></p><h3 id="_8-github-copilot-应用-智能体原生的桌面体验" tabindex="-1">8. GitHub Copilot 应用：智能体原生的桌面体验 <a class="header-anchor" href="#_8-github-copilot-应用-智能体原生的桌面体验" aria-label="Permalink to &quot;8. GitHub Copilot 应用：智能体原生的桌面体验&quot;">​</a></h3><p><strong>GitHub</strong> 在微软 Build 2026 期间发布 Copilot 应用相关更新，并将其定位为“智能体原生的桌面体验”。核心方向是让 AI 智能体用开发者熟悉的方式进入本地工作环境，而不是停留在聊天窗口里等指令 (^_^)v。来源：<a href="https://github.blog/news-insights/product-news/github-copilot-app-the-agent-native-desktop-experience" target="_blank" rel="noreferrer">GitHub Blog</a></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-开源框架-openwebrl-正式发布" tabindex="-1">1. 开源框架 OpenWebRL 正式发布 <a class="header-anchor" href="#_1-开源框架-openwebrl-正式发布" aria-label="Permalink to &quot;1. 开源框架 OpenWebRL 正式发布&quot;">​</a></h3><p><strong>OpenWebRL</strong> 面向真实网页环境中的智能体自进化训练，试图摆脱昂贵人工演示数据对规模化的限制。它让网页智能体在真实网络中学习任务执行路径，并把成功率推近闭源系统表现，对 Web agent 训练路线很值得跟进 🧠。来源：<a href="https://arxiv.org/abs/2606.02031" target="_blank" rel="noreferrer">arXiv</a></p><h3 id="_2-学者研发出全新-ai-正则化器" tabindex="-1">2. 学者研发出全新 AI 正则化器 <a class="header-anchor" href="#_2-学者研发出全新-ai-正则化器" aria-label="Permalink to &quot;2. 学者研发出全新 AI 正则化器&quot;">​</a></h3><p>这项研究提出新的正则化方法，用于降低模型训练方差并防止表征崩溃。源摘要中特别提到它在遥感监测任务中保持较高精度，同时骨干网络体积相对上代缩减 <strong>二十五倍</strong>，属于“更小但更稳”的工程型研究进展 ( •̀ ω •́ )。来源：<a href="https://arxiv.org/abs/2606.01443" target="_blank" rel="noreferrer">arXiv</a></p><h3 id="_3-视频生成新框架面世" tabindex="-1">3. 视频生成新框架面世 <a class="header-anchor" href="#_3-视频生成新框架面世" aria-label="Permalink to &quot;3. 视频生成新框架面世&quot;">​</a></h3><p>这项视频生成研究引入<strong>低秩潜变量</strong>压缩机制，用更紧凑的表示释放显存缓存压力；源材料提到可释放<strong>九成以上</strong>显存缓存，并在单张 <strong>B200 显卡</strong>上测试到明显提升。对视频生成来说，显存效率就是迭代速度，尤其影响长视频和高分辨率场景 🚀。来源：<a href="https://huggingface.co/papers/2605.30351" target="_blank" rel="noreferrer">Hugging Face Papers</a></p><p><video src="`+o+'" controls="controls" width="100%"></video></p><h3 id="_4-anthropic-可解释性研究-区分因果效应相似的特征" tabindex="-1">4. Anthropic 可解释性研究：区分因果效应相似的特征 <a class="header-anchor" href="#_4-anthropic-可解释性研究-区分因果效应相似的特征" aria-label="Permalink to &quot;4. Anthropic 可解释性研究：区分因果效应相似的特征&quot;">​</a></h3><p><strong>Anthropic</strong> 可解释性团队更新了 Circuits 研究进展，目标是区分那些激活模式相似、但因果效应不同的模型特征。新方法通过分析特征下游连接预测实际影响，并使用基于共激活统计的 <strong>TWERA</strong> 虚拟权重排序连接，帮助识别模型内部真正产生因果作用的组件 🧠。来源：<a href="https://transformer-circuits.pub/2026/may-update/index.html" target="_blank" rel="noreferrer">Transformer Circuits</a></p><h3 id="_5-codex-正在成为每个人的生产力工具" tabindex="-1">5. Codex 正在成为每个人的生产力工具 <a class="header-anchor" href="#_5-codex-正在成为每个人的生产力工具" aria-label="Permalink to &quot;5. Codex 正在成为每个人的生产力工具&quot;">​</a></h3><p>OpenAI 的 <strong>The Next Era of Knowledge Work</strong> 报告继续把 <strong>Codex</strong> 放到知识工作生产力框架里：研究、数据分析、工作流自动化和内容创作都能被 AI 增强。它的重点不是单点代码补全，而是让复杂知识任务被拆解、执行和复盘 (๑•̀ㅂ•́)و✧。来源：<a href="https://openai.com/index/codex-for-knowledge-work" target="_blank" rel="noreferrer">OpenAI</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-特朗普签新令审查发布前大模型" tabindex="-1">1. 特朗普签新令审查发布前大模型 <a class="header-anchor" href="#_1-特朗普签新令审查发布前大模型" aria-label="Permalink to &quot;1. 特朗普签新令审查发布前大模型&quot;">​</a></h3><p>美国政府发布新的 AI 行政令，要求在大模型正式发布前进行安全风险评估。政策目标是降低模型发布后的社会与安全隐患，同时官方也强调不是为了扼杀技术创新；对模型厂商来说，发布流程可能会更像安全审查流程 ⚖️。来源：<a href="https://www.theverge.com/policy/941775/trump-ai-executive-order" target="_blank" rel="noreferrer">The Verge</a></p><h3 id="_2-anthropic-扩展-project-glasswing-计划" tabindex="-1">2. Anthropic 扩展 Project Glasswing 计划 <a class="header-anchor" href="#_2-anthropic-扩展-project-glasswing-计划" aria-label="Permalink to &quot;2. Anthropic 扩展 Project Glasswing 计划&quot;">​</a></h3><p><strong>Anthropic</strong> 将 <strong>Project Glasswing</strong> 扩展至约 <strong>150 个</strong>新组织，此前首批约 <strong>50 个</strong>合作伙伴。新增伙伴覆盖十五个多国家，涉及电力、水务、医疗、通信和硬件等关键基础设施；项目使用 Claude Mythos Preview 等模型扫描漏洞并辅助修复，影响面可能超过 <strong>1 亿人</strong> 🔒。来源：<a href="https://www.anthropic.com/news/expanding-project-glasswing" target="_blank" rel="noreferrer">Anthropic</a></p><h3 id="_3-alphabet-拟融资-800-亿美元-anthropic-提交-ipo-申请" tabindex="-1">3. Alphabet 拟融资 800 亿美元，Anthropic 提交 IPO 申请 <a class="header-anchor" href="#_3-alphabet-拟融资-800-亿美元-anthropic-提交-ipo-申请" aria-label="Permalink to &quot;3. Alphabet 拟融资 800 亿美元，Anthropic 提交 IPO 申请&quot;">​</a></h3><p><strong>Alphabet</strong> 计划通过股权融资 <strong>800 亿美元</strong>，用于继续扩展 AI 基础设施。与此同时，<strong>Anthropic</strong> 已秘密提交 IPO 申请，HPE 也因 AI 基础设施需求旺盛上调年度销售预期，资本市场仍在给 AI 基建加速 💰。来源：<a href="https://www.bloomberg.com/news/videos/2026-06-02/bloomberg-tech-6-2-2026-video" target="_blank" rel="noreferrer">Bloomberg</a></p><h3 id="_4-sk-海力士计划未来五年内晶圆产能翻倍" tabindex="-1">4. SK 海力士计划未来五年内晶圆产能翻倍 <a class="header-anchor" href="#_4-sk-海力士计划未来五年内晶圆产能翻倍" aria-label="Permalink to &quot;4. SK 海力士计划未来五年内晶圆产能翻倍&quot;">​</a></h3><p><strong>SK 海力士</strong> 会长崔泰源表示，未来五年内计划将整体晶圆产能提高一倍，以应对 AI 数据中心和 AI PC 带来的存储需求。公司判断供需紧张可能延续至 <strong>2030 年</strong>，但新建晶圆厂至少需要三年，扩产仍会受到前置周期和资源成本约束 ☁️。来源：<a href="https://www.ithome.com/0/958/810.htm" target="_blank" rel="noreferrer">IT 之家</a></p><h3 id="_5-anthropic-支持美国-ai-行政令实施" tabindex="-1">5. Anthropic 支持美国 AI 行政令实施 <a class="header-anchor" href="#_5-anthropic-支持美国-ai-行政令实施" aria-label="Permalink to &quot;5. Anthropic 支持美国 AI 行政令实施&quot;">​</a></h3><p><strong>Anthropic</strong> 表态支持美国 AI 行政令的实施，并称这项政策是加强美国 AI 领导地位的重要一步。模型公司一边参与政策执行，一边推进安全产品与基础设施合作，监管和产业路线正在更紧密地绑在一起 ( •̀ ω •́ )。来源：<a href="https://x.com/AnthropicAI/status/2061924580222968183" target="_blank" rel="noreferrer">Anthropic</a></p><h3 id="_6-openai-呼吁通过全球领导力推进青年-ai-安全与机遇" tabindex="-1">6. OpenAI 呼吁通过全球领导力推进青年 AI 安全与机遇 <a class="header-anchor" href="#_6-openai-呼吁通过全球领导力推进青年-ai-安全与机遇" aria-label="Permalink to &quot;6. OpenAI 呼吁通过全球领导力推进青年 AI 安全与机遇&quot;">​</a></h3><p><strong>OpenAI</strong> 呼吁通过全球协作和专门 AI 安全研究机构，推进青少年 AI 使用安全与发展机会。这个议题的重点不只是限制风险，也包括让年轻用户在教育、创造和职业探索中获得更清晰的保护边界与机会 ⚖️。来源：<a href="https://openai.com/index/advancing-youth-safety-and-opportunity-through-global-leadership" target="_blank" rel="noreferrer">OpenAI</a></p><h3 id="_7-travelers-借助-openai-在全国部署-ai-理赔助手" tabindex="-1">7. Travelers 借助 OpenAI 在全国部署 AI 理赔助手 <a class="header-anchor" href="#_7-travelers-借助-openai-在全国部署-ai-理赔助手" aria-label="Permalink to &quot;7. Travelers 借助 OpenAI 在全国部署 AI 理赔助手&quot;">​</a></h3><p>美国保险公司 <strong>Travelers</strong> 与 <strong>OpenAI</strong> 合作部署 AI 驱动的 <strong>Claim Assistant</strong>，用于引导客户完成理赔流程并提供全天候支持。这类案例说明，企业 AI 落地正在从内部提效走向直接面向客户的高频服务场景 ☁️。来源：<a href="https://openai.com/index/travelers" target="_blank" rel="noreferrer">OpenAI</a></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-大模型输入压缩工具-headroom-开源-🌟6-3k" tabindex="-1">1. 大模型输入压缩工具 headroom 开源 🌟6.3k <a class="header-anchor" href="#_1-大模型输入压缩工具-headroom-开源-🌟6-3k" aria-label="Permalink to &quot;1. 大模型输入压缩工具 headroom 开源 🌟6.3k&quot;">​</a></h3><p><strong>headroom</strong> 是一个大模型输入压缩工具，目标是直接压缩送入模型的数据，降低 token 成本并保持回答质量。源材料提到数据体积可缩小<strong>九成以上</strong>，对于长上下文和批量分析任务来说很实用 🛠️。来源：<a href="https://github.com/chopratejas/headroom" target="_blank" rel="noreferrer">GitHub</a></p><h3 id="_2-多智能体金融框架-tradingagents-正式开源-🌟81-7k" tabindex="-1">2. 多智能体金融框架 TradingAgents 正式开源 🌟81.7k <a class="header-anchor" href="#_2-多智能体金融框架-tradingagents-正式开源-🌟81-7k" aria-label="Permalink to &quot;2. 多智能体金融框架 TradingAgents 正式开源 🌟81.7k&quot;">​</a></h3><p><strong>TradingAgents</strong> 是多智能体金融交易框架，试图用不同角色的 agent 协作处理市场分析、交易判断和风险评估。项目热度已经来到 <strong>81.7k</strong> 星级别，说明金融场景仍是 agent 框架最容易激发想象力的试验场 📈。来源：<a href="https://github.com/TauricResearch/TradingAgents" target="_blank" rel="noreferrer">GitHub</a></p><h3 id="_3-设计工具-impeccable-开源-🌟32-6k" tabindex="-1">3. 设计工具 impeccable 开源 🌟32.6k <a class="header-anchor" href="#_3-设计工具-impeccable-开源-🌟32-6k" aria-label="Permalink to &quot;3. 设计工具 impeccable 开源 🌟32.6k&quot;">​</a></h3><p><strong>impeccable</strong> 面向 AI 生成前端“能跑但不好看”的痛点，提供一组命令来优化网页视觉细节。源材料提到它包含 <strong>23 个命令</strong>，适合把 AI 写出的初版界面继续打磨到更像成品 ✨。来源：<a href="https://github.com/pbakaus/impeccable" target="_blank" rel="noreferrer">GitHub</a></p><h3 id="_4-ecc-智能体优化系统正式开源-🌟203k" tabindex="-1">4. ECC 智能体优化系统正式开源 🌟203k <a class="header-anchor" href="#_4-ecc-智能体优化系统正式开源-🌟203k" aria-label="Permalink to &quot;4. ECC 智能体优化系统正式开源 🌟203k&quot;">​</a></h3><p><strong>ECC</strong> 面向智能体性能瓶颈与安全风险做优化，关注工具调用、执行效率和系统稳定性。项目声量很高，源材料给出的社区关注达到 <strong>203k</strong> 星级别；如果这个数字后续持续稳定，它会是 agent 工程化方向的一个强信号 (๑•̀ㅂ•́)و。来源：<a href="https://github.com/affaan-m/ECC" target="_blank" rel="noreferrer">GitHub</a></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-ai-联盟携手杨立昆构建主权模型" tabindex="-1">1. AI 联盟携手杨立昆构建主权模型 <a class="header-anchor" href="#_1-ai-联盟携手杨立昆构建主权模型" aria-label="Permalink to &quot;1. AI 联盟携手杨立昆构建主权模型&quot;">​</a></h3><p>AI 联盟推进 <strong>Project Tapestry</strong>，与杨立昆等成员讨论主权模型和分布式训练路线。它的核心叙事是通过全球合作打破少数巨头对前沿模型能力的垄断，让更多地区和组织能训练、拥有并治理自己的模型 🤝。来源：<a href="https://thealliance.ai/blog/project-tapestry-the-path-to-frontier-sovereign-ai" target="_blank" rel="noreferrer">AI Alliance</a></p><h3 id="_2-商汤开源-sensenova-skills-ai-办公技能套件" tabindex="-1">2. 商汤开源 SenseNova-Skills AI 办公技能套件 <a class="header-anchor" href="#_2-商汤开源-sensenova-skills-ai-办公技能套件" aria-label="Permalink to &quot;2. 商汤开源 SenseNova-Skills AI 办公技能套件&quot;">​</a></h3><p><strong>商汤</strong> 开源 <strong>SenseNova-Skills</strong> AI 办公技能套件，面向任何技能兼容智能体，覆盖图像信息图表生成、数据分析、PPT 创建和深度研究四类能力。它更像是一组可复用的办公 agent 能力模块，而不是单一工具 🛠️。来源：<a href="https://x.com/SenseTime_AI/status/2061822148076093625" target="_blank" rel="noreferrer">SenseTime</a></p><h3 id="_3-开放模型的繁荣生态" tabindex="-1">3. 开放模型的繁荣生态 <a class="header-anchor" href="#_3-开放模型的繁荣生态" aria-label="Permalink to &quot;3. 开放模型的繁荣生态&quot;">​</a></h3><p>Tomer Tunguz 基于 OpenRouter 数据讨论开放模型生态：自 2025 年以来开放模型使用量显著增长，最新数据显示开放权重模型产生 <strong>69.1%</strong> 的 token 使用量，闭源模型为 <strong>30.9%</strong>。开放模型内部竞争也很快，DeepSeek、MiniMax、Kimi、MiMo、Qwen、腾讯 Hy3、阿里巴巴和 Arcee 等模型轮番改变份额格局 📈。来源：<a href="https://www.tomtunguz.com/the-thriving-ecosystem-of-open-models" target="_blank" rel="noreferrer">Tomer Tunguz</a></p><h3 id="快讯" tabindex="-1">快讯 <a class="header-anchor" href="#快讯" aria-label="Permalink to &quot;快讯&quot;">​</a></h3><ul><li><strong>英伟达微软揭露智能体安全漏洞。</strong> 研究者指出 AI agents 在系统稳定与安全边界上仍存在明显隐患，未来安全防御必须跟上 agent 能力扩张的速度 ⚠️。来源：<a href="https://www.reddit.com/r/artificial/comments/1tuwns4/nvidia_and_microsoft_researchers_say_ai_agents/" target="_blank" rel="noreferrer">Reddit</a></li><li><strong>Claude Code 团队实践：智能体编程如何重塑工程组织与流程。</strong> Claude Code 工程团队分享 AI-native 研发组织经验，瓶颈正在从写代码转向验证、审查和安全维护。来源：<a href="https://claude.com/blog/running-an-ai-native-engineering-org" target="_blank" rel="noreferrer">Claude</a></li><li><strong>Claude Code 自我检查与反馈闭环技巧。</strong> Claude Devs 分享如何把人工检查编码成工作流，让 Claude Code 在交付前自动做自检和反馈闭环。来源：<a href="https://x.com/ClaudeDevs/status/2061900434722496604" target="_blank" rel="noreferrer">Claude Devs</a></li><li><strong>Gemini Spark 带来强烈 AI agent 体验。</strong> The Verge 体验认为 Gemini Spark 的行程规划能力令人印象深刻，但也带来对 agent 权限和影响力的复杂感受 ( •̀ ω •́ )。来源：<a href="https://www.theverge.com/ai-artificial-intelligence/941388/gemini-spark-ai-agent-trip-planning" target="_blank" rel="noreferrer">The Verge</a></li><li><strong>Gary Marcus 继续质疑可信 AI 路线。</strong> Gary Marcus 从数学局限和人类心理复杂性出发，讨论 AI 系统为何仍可能在可信赖性上出现根本问题。来源：<a href="https://garymarcus.substack.com/p/why-things-will-eventually-fall-apart" target="_blank" rel="noreferrer">Gary Marcus</a></li></ul><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>Agent 正在从聊天框走向运行环境。</strong> Devin Desktop、Claude Code 工作流和 Copilot 桌面体验都在把 agent 放进真实文件、任务和工程上下文里 🚀。</li><li><strong>效率型研究仍然很关键。</strong> 视频生成显存压缩、网页智能体自进化和可解释性工具都说明，底层约束不解决，上层产品会很快撞墙 🧠。</li><li><strong>安全治理不再是后置话题。</strong> 行政令、Project Glasswing 和青少年 AI 安全都在把发布前评估和使用边界推到前台 ⚖️。</li><li><strong>AI 基建继续吃掉资本开支。</strong> 800 亿美元融资、存储扩产和行业理赔助手共同说明，算力、存储和业务系统会一起扩张 ☁️。</li><li><strong>开源工具仍是扩散最快的那层。</strong> 从 headroom 到 ECC，真正能嵌入工作流的小工具会持续把模型能力变成日常生产力 🛠️。</li></ul>',67)])])}const b=a(s,[["render",i]]);export{u as __pageData,b as default};
